function chunkText(text, target = 768, tolerance = 200) {
  const chunks = [];
  let pos = 0;
  const len = text.length;

  const minSize = Math.max(1, target - tolerance);
  const maxSize = target + tolerance;

  while (pos < len) {
    const remaining = len - pos;

    // If what's left fits within maxSize, just take it all.
    if (remaining <= maxSize) {
      chunks.push(text.slice(pos).trim());
      break;
    }

    // Search window for a good split point: [pos+minSize, pos+maxSize]
    const windowStart = pos + minSize;
    const windowEnd = Math.min(pos + maxSize, len);

    let splitIndex = -1;

    // Prefer the last newline within the window
    let lastNewline = text.lastIndexOf('\n', windowEnd - 1);
    if (lastNewline >= windowStart) {
      splitIndex = lastNewline + 1; // include the newline in the current chunk
    }

    // Otherwise, try the last dot within the window
    if (splitIndex === -1) {
      let lastDot = text.lastIndexOf('.', windowEnd - 1);
      if (lastDot >= windowStart) {
        splitIndex = lastDot + 1; // include the dot
      }
    }

    // Fallback: no newline/dot found in window -> hard cut at target
    if (splitIndex === -1) {
      splitIndex = pos + target;
    }

    chunks.push(text.slice(pos, splitIndex).trim());
    pos = splitIndex;

    // Skip leading whitespace/newlines for the next chunk
    while (pos < len && /\s/.test(text[pos])) {
      pos++;
    }
  }

  return chunks.filter(c => c.length > 0);
}

const targetText = $input.first().json.text;
const chunksSize = 768;
const tolerance = 200;

const chunks = chunkText(targetText, chunksSize, tolerance);
const chunksLenght = chunks.length

return [
  {
    ...$input.first().json,
    text: undefined,
    chunks: chunks.map((currentChunk, index) => ({
      json: {
        chunk: currentChunk,
        source: $input.first().json.source,
        chunkIndex: index,
        totalChunks: chunksLenght,
        sourceLength: targetText.length
      }
    }))
  }
]
